import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"设置与隐私","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/settings-privacy.md","filePath":"guide/misskey/settings-privacy.md","lastUpdated":1789295632000}'),l={name:"guide/misskey/settings-privacy.md"};function s(o,a,n,h,d,u){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="设置与隐私" tabindex="-1">设置与隐私 <a class="header-anchor" href="#设置与隐私" aria-label="Permalink to &quot;设置与隐私&quot;">​</a></h1><p>通过侧栏「设置」进入。设置项较多，这里按使用场景介绍最常用的部分。</p><h2 id="个人资料" tabindex="-1">个人资料 <a class="header-anchor" href="#个人资料" aria-label="Permalink to &quot;个人资料&quot;">​</a></h2><ul><li>头像、头图、昵称、简介（支持 <a href="/guide/misskey/mfm">MFM 语法</a>）、生日、所在地、URL 等字段。</li><li>佩戴<a href="/guide/misskey/achievements">头像挂件</a>。</li><li>可以创建多个<strong>资料档案</strong>（如公开版、创作版）并随时切换。</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><ul><li><strong>锁推（锁定账号）</strong>：开启后其他用户需要你批准才能关注你。注意：只要帖子可见范围不是「仅关注者」，任何人仍能看到帖子本身。</li><li><strong>关注 / 粉丝列表可见性</strong>：公开 / 只有关注你的用户能看到 / 私密。</li><li><strong>将回应设置为公开</strong>：控制你发出的回应是否公开可见。</li><li><strong>帖子默认可见范围</strong>：可设为公开、仅首页、仅关注者等。</li></ul><h2 id="屏蔽与过滤" tabindex="-1">屏蔽与过滤 <a class="header-anchor" href="#屏蔽与过滤" aria-label="Permalink to &quot;屏蔽与过滤&quot;">​</a></h2><p>「设置 → 屏蔽与过滤」提供多层过滤：</p><ul><li><strong>折叠关键词</strong>：命中的帖子折叠显示，点开仍可看。</li><li><strong>屏蔽关键词</strong>：命中的帖子完全隐藏。</li><li><strong>隐藏用户 / 屏蔽用户</strong>：隐藏是不再显示对方内容；屏蔽是彻底断绝互动，对方无法关注你、回应你。</li><li><strong>屏蔽实例（服务器）</strong>：整体屏蔽来自某个服务器的内容。</li></ul><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><ul><li>按类型开关通知：关注、提及、回应、转发、引用、投票、<a href="/guide/messages">消息</a>等。</li><li>可配置主界面通知、推送通知的行为。</li></ul><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><ul><li><strong>两步验证（2FA）</strong>：强烈建议开启，支持 TOTP 应用和安全密钥，扫码绑定。</li><li><strong>登录历史</strong>：查看近期登录记录，发现异常及时改密码。</li></ul><h2 id="服务连接与账户数据" tabindex="-1">服务连接与账户数据 <a class="header-anchor" href="#服务连接与账户数据" aria-label="Permalink to &quot;服务连接与账户数据&quot;">​</a></h2><ul><li>「服务连接」：生成访问令牌，供 <a href="/guide/aliya-web">Aliya Web</a>、<a href="/guide/third-party">第三方应用</a>等外部程序使用。</li><li>「账户数据」：导入 / 导出你的数据（关注列表、帖子存档等）。</li></ul><h2 id="其他值得了解的" tabindex="-1">其他值得了解的 <a class="header-anchor" href="#其他值得了解的" aria-label="Permalink to &quot;其他值得了解的&quot;">​</a></h2><ul><li><strong>邮件</strong>：绑定邮箱用于接收验证和通知。</li><li><strong>外观偏好</strong>：默认字体大小、表情面板、发帖表单行为等。</li><li><strong>网盘设置</strong>：见<a href="/guide/misskey/drive">网盘</a>。</li></ul>',17)])])}const m=i(l,[["render",s]]);export{c as __pageData,m as default};
